function el(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;}
function link(label,url){const a=el('a',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener';return a;}
function links(p){const n=el('div',null,'links');if(p.paper)n.append(link(p.venue.startsWith('Preprint')?'Preprint':'Paper',p.paper));if(p.scholar)n.append(link('Google Scholar',p.scholar));if(p.docs)n.append(link('Documentation',p.docs));if(p.code)n.append(link('Code',p.code));return n;}
function card(p,withFigure=true){const a=el('article',null,'work');a.dataset.paper=p.key;if(withFigure&&p.image){const f=el('button',null,'figure');f.type='button';f.setAttribute('aria-label','Enlarge figure: '+p.title);const im=el('img');im.src=p.image;im.alt=p.credit||p.title;im.loading='lazy';f.append(im);f.addEventListener('click',()=>{const d=root.querySelector('#figure-dialog');d.querySelector('img').src=p.image;d.querySelector('img').alt=im.alt;d.querySelector('p').textContent=p.credit||p.title;d.showModal();});a.append(f);const c=el('div',null,'credit');c.append(el('span',p.credit||'Original figure'));if(p.figureSource||p.paper||p.code)c.append(document.createTextNode(' · '),link('Source',p.figureSource||p.paper||p.code));a.append(c);}else if(withFigure){a.append(el('p',p.paper?'Figure unavailable from the public source.':'Forthcoming manuscript · figure to follow.','credit'));}a.append(el('div',p.venue,'eyebrow'),el('h3',p.title),el('p',p.desc),links(p));return a;}

